bun -e '
import { parseDispatchEmail } from "./src/providers/email.ts";
import { readFileSync } from "node:fs";
const files = ["amazon.txt","mercadolibre.txt","ebay.txt","alibaba.txt","homecenter.txt"];
for (const f of files) {
  const raw = readFileSync("fixtures/correos/"+f, "utf8");
  const head = raw.split(/\r?\n\r?\n/)[0] ?? "";
  const from = head.match(/^From:[ \t]*(.*)$/im)?.[1]?.trim() ?? "(sin From)";
  const parsed = parseDispatchEmail(raw);
  console.log(f, "FROM:", JSON.stringify(from), "PARSED:", JSON.stringify(parsed));
}
const caso = readFileSync("harness/casos/caso3-ml-reenviado.txt","utf8");
console.log("CASO", JSON.stringify(parseDispatchEmail(caso)));
'

